<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Illuminate\Http\JsonResponse; use Pterodactyl\Models\Server; use Pterodactyl\Models\Dezerx\FreeServer; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Services\Dezerx\ServerCreate\Discord; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreate; use Pterodactyl\Services\Dezerx\ServerCreate\ServerFactory; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreatePresenter; use Pterodactyl\Services\Servers\BuildModificationService; use Pterodactyl\Services\Servers\ServerDeletionService; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class ServerCreateController extends ClientApiController { public function __construct( private ServerCreatePresenter $presenter, private ServerFactory $factory, private BuildModificationService $build, private ServerDeletionService $deletion, ) { parent::__construct(); } public function index(ClientApiRequest $request): JsonResponse { if (!ServerCreate::enabled()) { throw new NotFoundHttpException(); } return new JsonResponse($this->presenter->page($request->user())); } public function summary(ClientApiRequest $request): JsonResponse { if (!ServerCreate::enabled()) { return new JsonResponse([ 'enabled' => false, 'available' => false, 'refusal' => 'unavailable', 'remaining' => 0, 'held' => 0, 'renewals' => $this->presenter->renewals(), 'servers' => [], ]); } return new JsonResponse($this->presenter->summary($request->user())); } public function store(ClientApiRequest $request): JsonResponse { if (!ServerCreate::enabled()) { throw new NotFoundHttpException(); } $data = $request->validate([ 'egg' => ['required', 'string', 'max:64'], 'location' => ['required', 'integer', 'min:1'], 'name' => ['required', 'string', 'max:40'], 'environment' => ['sometimes', 'array', 'max:64'], 'environment.*' => ['nullable', 'string', 'max:255'], 'resources' => ['sometimes', 'array', 'max:8'], 'resources.*' => ['nullable', 'integer', 'min:0', 'max:10485760'], ]); $egg = ServerCreate::egg($data['egg']); if ($egg === null) { throw new DisplayException('That is not a server this panel offers.'); } $name = $this->factory->cleanName($data['name']); if ($name === '') { throw new DisplayException('Give the server a name.'); } $server = $this->factory->create( $request->user(), $egg, (int) $data['location'], $name, (array) ($data['environment'] ?? []), (array) ($data['resources'] ?? []), ); return new JsonResponse([ 'uuid' => $server->uuid, 'identifier' => $server->uuidShort, 'name' => $server->name, ], JsonResponse::HTTP_CREATED); } public function unlink(ClientApiRequest $request): JsonResponse { if (!ServerCreate::enabled() || !Discord::required()) { throw new NotFoundHttpException(); } $user = $request->user(); if ($user->demo) { throw new DisplayException('The demo account cannot unlink Discord.'); } if (!Discord::linked($user)) { throw new DisplayException('There is no Discord account linked to this one.'); } $this->factory->serialised(function () use ($user) { $held = ServerCreate::held($user); if ($held > 0) { throw new DisplayException( $held === 1 ? 'Delete your free server before unlinking Discord.' : 'Delete your free servers before unlinking Discord.', ); } Discord::unlink($user); }); return new JsonResponse([], JsonResponse::HTTP_NO_CONTENT); } public function manage(ClientApiRequest $request, Server $server): JsonResponse { if (!ServerCreate::enabled()) { throw new NotFoundHttpException(); } $this->owned($request, $server); return new JsonResponse($this->presenter->manage($request->user(), $server)); } public function resize(ClientApiRequest $request, Server $server): JsonResponse { if (!ServerCreate::enabled() || !ServerCreate::custom()) { throw new NotFoundHttpException(); } $this->owned($request, $server); if ($request->user()->demo) { throw new DisplayException('The demo account cannot resize a server.'); } $data = $request->validate([ 'resources' => ['required', 'array', 'max:8'], 'resources.*' => ['nullable', 'integer', 'min:0', 'max:10485760'], ]); $this->factory->serialised(function () use ($request, $server, $data) { $server->refresh(); $wanted = ServerCreate::chosen($request->user(), (array) $data['resources'], $server->id); $this->build->handle($server, [ 'memory' => $wanted['memory'], 'swap' => $server->swap, 'io' => $server->io, 'cpu' => $wanted['cpu'], 'threads' => $server->threads, 'disk' => $wanted['disk'], 'database_limit' => $wanted['databases'], 'allocation_limit' => $wanted['allocations'], 'backup_limit' => $wanted['backups'], 'oom_disabled' => $server->oom_disabled, ]); }); return new JsonResponse($this->presenter->manage($request->user(), $server->refresh())); } public function destroy(ClientApiRequest $request, Server $server): JsonResponse { if (!ServerCreate::enabled()) { throw new NotFoundHttpException(); } $this->owned($request, $server); if ($request->user()->demo) { throw new DisplayException('The demo account cannot delete a server.'); } $this->deletion->handle($server); return new JsonResponse([], JsonResponse::HTTP_NO_CONTENT); } public function renewal(ClientApiRequest $request, Server $server): JsonResponse { if (!ServerCreate::enabled()) { throw new NotFoundHttpException(); } return new JsonResponse($this->presenter->entry($this->owned($request, $server))); } public function renew(ClientApiRequest $request, Server $server): JsonResponse { if (!ServerCreate::enabled() || !ServerCreate::renewals()) { throw new NotFoundHttpException(); } $entry = $this->owned($request, $server); if (!ServerCreate::withinWindow($entry->renew_at)) { throw new DisplayException( 'This server cannot be renewed yet. Come back closer to its renewal date.', ); } return new JsonResponse($this->presenter->entry($this->factory->renew($entry))); } private function owned(ClientApiRequest $request, Server $server): FreeServer { if ($server->owner_id !== $request->user()->id) { throw new NotFoundHttpException(); } $entry = FreeServer::query()->with('server')->where('server_id', $server->id)->first(); if ($entry === null) { throw new NotFoundHttpException(); } return $entry; } } 